
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_mb88_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_mb88", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.209212680688488e+00, -4.125929109225565e+00, -4.009258183606065e+00, -3.847703204282330e+00, -3.627702234384922e+00, -3.335208172152784e+00, -2.959466065788996e+00, -2.499974221487221e+00, -1.976631955056206e+00, -1.439421730569127e+00, -9.649274677186268e-01, -6.842333989769421e-01, -5.935439567295733e-01, -4.817553758942398e-01, -3.405285777793738e-01, -2.114012909796674e-01, -1.247113503003404e-01, -8.169126623132311e-02, -5.841227900574955e-02, -4.154233313645115e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


